/**
 * A cited letter draft about one issue in one area, from POST /areas/{kind}/{id}/letters. Addressed by office only, neutral wording. Nothing is filed automatically; the resident files it.
 */
export interface AreaLetterDraft {
  letter_id: string;
  area: {
    kind: "ward" | "assembly" | "loksabha" | "district";
    id: string;
    name: string;
  };
  /**
   * The report type the letter is about; all covers every type in the area.
   */
  issue:
    | "waste_dump"
    | "no_bin"
    | "contaminated_water"
    | "open_construction"
    | "overflowing_bin"
    | "all";
  /**
   * Offices responsible for the area kind: ward and assembly, the head of each local body with sites there; loksabha and district, the District Collector of each district, then the local body heads.
   *
   * @minItems 1
   */
  to: [
    {
      /**
       * For example Commissioner or District Collector.
       */
      office: string;
      /**
       * For example Jodhpur Municipal Corporation, or Jodhpur district, Rajasthan.
       */
      body: string;
    },
    ...{
      /**
       * For example Commissioner or District Collector.
       */
      office: string;
      /**
       * For example Jodhpur Municipal Corporation, or Jodhpur district, Rajasthan.
       */
      body: string;
    }[]
  ];
  /**
   * At most one line, the area's own seat, for attention: the ward councillor, the MLA, or the MP (never for an outdated Lok Sabha seat). Empty for a district or when no representative is listed.
   */
  cc: {
    office: "councillor" | "mla" | "mp";
    seat: {
      id: string;
      name: string;
    };
    marking: "for attention";
  }[];
  subject: string;
  /**
   * Letter prose. May be regional; quotes inside stay in the official English or Hindi.
   */
  body: string;
  language: "en" | "hi";
  /**
   * @minItems 1
   */
  citations: [
    {
      rule_id: string;
      document: string;
      clause: string;
      quote: string;
      /**
       * SHA-256 of the official PDF the rule comes from.
       */
      source_sha256: string;
      verified: true;
    },
    ...{
      rule_id: string;
      document: string;
      clause: string;
      quote: string;
      /**
       * SHA-256 of the official PDF the rule comes from.
       */
      source_sha256: string;
      verified: true;
    }[]
  ];
  /**
   * verified must equal total and the length of citations, as for letter_draft.
   */
  verifier: {
    verified: number;
    total: number;
  };
  template_fallback: boolean;
  provider: "bedrock" | "openai" | "openrouter" | "rekognition" | "comprehend" | "junksnap";
  model: string;
  version: string;
  created_at: string;
  /**
   * What the letter rests on, for the app to show and print with it. Counts cover the issue's sites in the area that are not rejected; verified_reports counts verified sites only.
   */
  evidence: {
    reports: number;
    /**
     * Distinct people (user id, else device) across those sites; null when no site has reporter ids yet.
     */
    reporters: number | null;
    verified_reports: number;
    sites: number;
    first_reported_at: string;
    last_reported_at: string;
    /**
     * Up to 5 verified sites with the most verified reports, open and reopened before cleaned.
     *
     * @minItems 1
     */
    worst_sites: [
      {
        site_id: string;
        report_type:
          "waste_dump" | "no_bin" | "contaminated_water" | "open_construction" | "overflowing_bin";
        context: string;
        status: "open" | "cleaned" | "reopened";
        report_count: number;
        verified_count: number;
        first_reported_at: string;
        last_reported_at: string;
        /**
         * Blurred public copies only.
         *
         * @maxItems 6
         */
        photo_urls:
          | []
          | [string]
          | [string, string]
          | [string, string, string]
          | [string, string, string, string]
          | [string, string, string, string, string]
          | [string, string, string, string, string, string];
        /**
         * The site's measured insights, as in letter_draft.evidence.insights; null when the site has none.
         */
        insights: null | {
          reports: number;
          composition: {
            material: string;
            share_pct: number;
            reports: number;
          }[];
          size_class: "small" | "medium" | "large" | null;
          hazards: string[];
          near: {
            kind: "school" | "hospital" | "water" | "drain";
            distance_m: number;
          }[];
        };
      },
      ...{
        site_id: string;
        report_type:
          "waste_dump" | "no_bin" | "contaminated_water" | "open_construction" | "overflowing_bin";
        context: string;
        status: "open" | "cleaned" | "reopened";
        report_count: number;
        verified_count: number;
        first_reported_at: string;
        last_reported_at: string;
        /**
         * Blurred public copies only.
         *
         * @maxItems 6
         */
        photo_urls:
          | []
          | [string]
          | [string, string]
          | [string, string, string]
          | [string, string, string, string]
          | [string, string, string, string, string]
          | [string, string, string, string, string, string];
        /**
         * The site's measured insights, as in letter_draft.evidence.insights; null when the site has none.
         */
        insights: null | {
          reports: number;
          composition: {
            material: string;
            share_pct: number;
            reports: number;
          }[];
          size_class: "small" | "medium" | "large" | null;
          hazards: string[];
          near: {
            kind: "school" | "hospital" | "water" | "drain";
            distance_m: number;
          }[];
        };
      }[]
    ];
    /**
     * The area's measured scores from ward_scores; withheld scores are left out. verified_reports is the count the scores rest on (all issues).
     */
    scores: {
      name: "city" | "citizen" | "bin_access";
      value: number;
      verified_reports: number;
    }[];
    /**
     * For waste_dump, no_bin and all: of the issue's verified sites, how many had bin access measured and how many have no known bin within 3 km. Null for other issues.
     */
    bin_access: null | {
      sites_measured: number;
      sites_without_bin_within_3km: number;
    };
  };
}

